const b = $input.first().json.body || $input.first().json;
const name = String(b.business_name || '').trim().slice(0, 120);
const industry = String(b.industry || '').trim().slice(0, 160);
const email = String(b.email || '').trim().slice(0, 160);
if (!name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
  throw new Error('Invalid submission');
}
// First significant word is usually the distinctive element worth searching
const stop = new Set(['the','a','an','llc','inc','co','company','of','and']);
const words = name.toLowerCase().replace(/[^a-z0-9 ]/g, '').split(/\s+/).filter(w => w && !stop.has(w));
const searchTerm = words[0] || name.toLowerCase();
return [{ json: { business_name: name, industry, email, searchTerm, ts: new Date().toISOString() } }];

const resp = $input.first().json;
if (resp.stop_reason === 'refusal') {
  throw new Error('Model declined to produce report');
}
const html = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('').replace(/^```html\n?|```$/g, '').trim();
if (!html) throw new Error('Empty report');
const lead = $('Validate Input').first().json;
return [{ json: { html, email: lead.email, business_name: lead.business_name, industry: lead.industry, ts: lead.ts } }];
